29	    const normalizeData = (normalize ? getNormalizeData(filteredData) : filteredData);
30	
31	    let path = ``;
32	    
33	
34	    const fixHeight = (type != 'bars' ?  (height+top*2) / 2 : height+top);
35	    const fixWidth = width / samples;
36	    const pathslength = paths.length;
37	    const fixpathslength =  (type == 'mirror' ? pathslength*2 : pathslength);
