60	                let k = j;
61	                if(j >= pathslength) {
62	                    k = j - pathslength;
63	                    mirror = -1;   
64	                }
65	                paths[k].minshow = paths[k].minshow ?? 0;
66	                paths[k].maxshow = paths[k].maxshow ?? 1;
67	                paths[k].normalize = paths[k].normalize ?? false;
