80	                            if(pos_x !== last_pos_x || pos_y !== last_pos_y) {   
81	                                path += `M ${pos_x} ${pos_y} `;
82	                            }
83	
84	                            path += `L ${end_pos_x} ${end_pos_y} `; 
85	                            
86	                            last_pos_x = end_pos_x;
87	                            last_pos_y = end_pos_y;                             
