94	
95	                            //const end_pos_x = ((i+1) * fixWidth) - (fixWidth*(1-(paths[k].ex/100))) + left;
96	                            const end_pos_x = (i*fixWidth) + (fixWidth*paths[k].ex/100) + left;
97	                            const end_pos_y = pos_y;
98	
99	                            if(pos_x !== last_pos_x || pos_y !== last_pos_y) {   
100	                                path += `M ${pos_x} ${pos_y} `;
101	                            }
102	
103	                            path += `H ${end_pos_x} `; 
104	                            
105	                            last_pos_x = end_pos_x;
106	                            last_pos_y = end_pos_y;                             
107	                            break;
108	                        }
109	                        
110	                        case 'V': {
111	                            const pos_x = (i * fixWidth)  + (fixWidth*paths[k].x/100) + left;
