143	
144	                            path += `C ${pos_x} ${pos_y} ${center_pos_x} ${center_pos_y} ${end_pos_x} ${end_pos_y} `; 
145	
146	                            last_pos_x = end_pos_x;
147	                            last_pos_y = end_pos_y;
