420	const getFramesData = (audioBuffer, channel, animation, animationframes) => {
421	    const rawData = audioBuffer.getChannelData(channel);
422	    
423	    const framesData = [];
424	    if(animation) {
425	        const frames = audioBuffer.sampleRate / animationframes;
426	        for (let index = 0; index < rawData.length; index += frames) {
427	            const partraw = rawData.slice(index, index+frames);
428	            framesData.push(partraw);
429	        }
430	    } else {
431	        framesData.push(rawData);
432	    }
433	
434	    return framesData;
435	}
436	
437	const getFilterData = (framesData, samples) => {
438	    const filteredData = [];
439	    const framesDataLength = framesData.length;
440	    for(let f = 0; f < framesDataLength; f++) {
441	        const blockSize = Math.floor(framesData[f].length / samples); // the number of samples in each subdivision
442	        const filteredDataBlock = [];
443	        for (let i = 0; i < samples; i++) {
444	            let blockStart = blockSize * i; // the location of the first sample in the block
445	            let sum = 0;
446	            for (let j = 0; j < blockSize; j++) {
447	                sum = sum + Math.abs(framesData[f][blockStart + j]); // find the sum of all the samples in the block
448	            }
449	            filteredDataBlock.push(sum / blockSize); // divide the sum by the block size to get the average
450	        }
451	        filteredData.push(filteredDataBlock);
452	    }
453	    return filteredData;   
454	}
455	
456	const getNormalizeData = (filteredData) => {
457	    const multipliers = [];
458	    const filteredDataLength = filteredData.length
459	    for(let i = 0; i < filteredDataLength; i++) {
460	        const multiplier = Math.max(...filteredData[i]);
461	        multipliers.push(multiplier);
462	    }
463	    const maxMultiplier = Math.pow(Math.max(...multipliers), -1);
464	
465	    const normalizeData = [];
466	    for(let i = 0; i < filteredDataLength; i++) {
467	        const normalizeDataBlock = filteredData[i].map(n => n * maxMultiplier);
468	        normalizeData.push(normalizeDataBlock);
469	    }
470	    return normalizeData;
471	}

