        paths: [{ d: 'V', sy: 0, x: 50, ey: 100 }],
    },
    {
        samples: 137, type: 'mirror', top: 20,
        paths: [{ d: 'Q', sx: 20, sy: 0, x: 50, y: 100, ex: 80, ey: 0 }],
    },
