test('linearPath: byte-identical d strings vs legacy on constant-magnitude buffer', () => {
    for (const options of linearOptionSets) {
        assert.equal(
            linearPath(uniformBuffer, options),
            legacy.linearPath(uniformBuffer, options),
            `linear options ${JSON.stringify(options)}`
        );
