test('rendered node count scales with samples, not buffer length', () => {
    const shortBuffer = new MockAudioBuffer([randomSignal(GRANULARITY * 2, 21)]);
    const longBuffer = new MockAudioBuffer([randomSignal(GRANULARITY * 8, 22)]);
