import * as next from './src/waveform-core.mjs';
import * as legacy from './test/legacy-waveform-path.mjs';

const N = 44100 * 60; // 60 minutes? no: 60 seconds of 44.1kHz mono = 2.646M samples
const data = Float32Array.from({ length: N }, (_, i) => Math.sin(i * 0.03) * 0.7);
const buffer = {
    numberOfChannels: 1, length: N, sampleRate: 44100,
    getChannelData: () => data,
};

const countCommands = (d) => d.split(/\s*[MLHCQVAZ]\s*/).length - 1;
const options = { samples: 100, type: 'steps', top: 20 };

const time = (fn, runs) => {
    const start = process.hrtime.bigint();
    let last;
    for (let i = 0; i < runs; i++) last = fn(i);
    return { ms: Number(process.hrtime.bigint() - start) / 1e6, last };
};

// Warm up caches.
next.linearPath(buffer, options);

const legacyOne = time(() => legacy.linearPath(buffer, options), 1);
const nextOne = time(() => next.linearPath(buffer, { ...options }), 1);
const legacyDrag = time((i) => legacy.linearPath(buffer, { ...options, width: 800 + (i % 2) }), 20);
const nextDrag = time((i) => next.linearPath(buffer, { ...options, width: 800 + (i % 2) }), 20);

console.log(`buffer: ${N} PCM samples`);
console.log(`legacy single render: ${legacyOne.ms.toFixed(1)} ms`);
console.log(`new single render (cache warm): ${nextOne.ms.toFixed(2)} ms`);
console.log(`legacy 20 resize renders: ${legacyDrag.ms.toFixed(1)} ms`);
console.log(`new 20 resize renders: ${nextDrag.ms.toFixed(2)} ms`);
console.log(`legacy nodes: ${countCommands(legacyOne.last)}, new nodes: ${countCommands(nextOne.last)}`);
console.log(`node count equal: ${countCommands(legacyOne.last) === countCommands(nextOne.last)}`);

// Granule-layer cost on a fresh long buffer (the one-time full scan).
const fresh = {
    numberOfChannels: 1, length: N, sampleRate: 44100,
    getChannelData: () => Float32Array.from(data),
};
const t = time(() => next.linearPath(fresh, options), 1);
console.log(`new cold render (granule build + first path): ${t.ms.toFixed(1)} ms`);

