    report(oggLines);
} catch (error) {
    const lines = [...synthLines, '', 'OGG DECODE SKIPPED/FAILED: ' + (error && error.message || error)];
    report(lines);
}

import * as next from '../docs/waveform-path.min.js';
import * as legacy from '../test/legacy-waveform-path.mjs';

const out = document.getElementById('out');
const report = (lines) => {
    const text = lines.join('\n');
    out.textContent = text;
    document.title = 'DONE\n' + text;
};
window.addEventListener('error', (event) => {
    document.title = 'PAGE-ERROR\n' + (event.error && event.error.stack || event.message);
});
document.title = 'STARTED';

// Move commands (M) are emitted by coordinate-based deduplication, which
// legitimately changes when min/max replaces the old block average; compare
// the draw-command skeleton instead, and surface M counts separately.
const skeleton = (d) => (d.match(/[LHCQVAZ]/g) || []).join('');
const countCommands = (d) => d.split(/\s*[MLHCQVAZ]\s*/).length - 1;
const countMoves = (d) => (d.match(/M/g) || []).length;

const runChecks = (audioData, label, lines) => {
    lines.push(`[${label}] ${audioData.length} samples, ${audioData.numberOfChannels} ch, ${audioData.sampleRate} Hz`);

    const cases = [
        ['linear logo', 'linear', { samples: 100, type: 'steps', top: 20 }],
        ['linear L-pair', 'linear', { samples: 100, type: 'steps', top: 20, paths: [
            { d: 'L', sx: 0, sy: 0, ex: 50, ey: 100 },
            { d: 'L', sx: 50, sy: 100, ex: 100, ey: 0 },
        ] }],
        ['linear mirror V', 'linear', { samples: 100, type: 'mirror', top: 20, paths: [{ d: 'V', sy: 0, x: 50, ey: 100 }] }],
        ['linear Q mirror', 'linear', { samples: 75, type: 'mirror', top: 20, paths: [{ d: 'Q', sx: 20, sy: 0, x: 50, y: 100, ex: 80, ey: 0 }] }],
        ['linear bars', 'linear', { samples: 100, type: 'bars', top: 20, paths: [{ d: 'V', sy: 0, x: 50, ey: 100 }] }],
        ['linear arc mix', 'linear', { samples: 50, type: 'steps', top: 20, paths: [
            { d: 'V', sy: 0, x: 0, ey: 100 },
            { d: 'A', sx: 0, sy: 100, ex: 100, ey: 100, rx: 10, ry: 10, angle: 180, arc: 1, sweep: 1 },
        ] }],
        ['linear animation', 'linear', { samples: 100, type: 'steps', top: 20, animation: true }],
        ['polar steps', 'polar', { samples: 90, type: 'steps', left: 200, top: 200, distance: 100, length: 50 }],
        ['polar bars', 'polar', { samples: 90, type: 'bars', left: 200, top: 200, distance: 75, length: 75, paths: [{ d: 'L', sdeg: 50, sr: 0, edeg: 50, er: 100 }] }],
        ['polar mirror', 'polar', { samples: 90, type: 'mirror', left: 200, top: 200, distance: 100, length: 100 }],
        ['polar inverted', 'polar', { samples: 90, type: 'steps', left: 200, top: 200, distance: 100, length: 100, startdeg: 270, enddeg: 90, invertdeg: true, invertpath: true }],
        ['polar animation', 'polar', { samples: 90, type: 'steps', left: 200, top: 200, distance: 100, length: 100, animation: true }],
    ];

    let allStructureMatch = true;
    let anyNaN = false;
    for (const [name, mode, options] of cases) {
        const newPath = mode === 'linear' ? next.linearPath(audioData, options) : next.polarPath(audioData, options);
        const oldPath = mode === 'linear' ? legacy.linearPath(audioData, options) : legacy.polarPath(audioData, options);
        const structureMatch = skeleton(newPath) === skeleton(oldPath)
            && countCommands(newPath) - countMoves(newPath) === countCommands(oldPath) - countMoves(oldPath);
        allStructureMatch &&= structureMatch;
        anyNaN ||= newPath.includes('NaN');
        lines.push(`${name.padEnd(18)} nodes=${String(countCommands(newPath)).padStart(5)}(M:${countMoves(newPath)})  shapeMatch=${structureMatch}  dLen=${newPath.length}`);
    }
    lines.push(`ALL SHAPES MATCH: ${allStructureMatch}`);
    lines.push(`NO NaN IN OUTPUT: ${!anyNaN}`);

    const entry = next.getStatsEntry(audioData);
    const granuleCount = entry.granMin.length;
    next.linearPath(audioData, { samples: 100 });
    next.polarPath(audioData, { samples: 100, left: 200, top: 200 });
    lines.push(`granules=${granuleCount}, shared entry after mode switch: ${next.getStatsEntry(audioData) === entry}`);
    lines.push(`path cache holds both modes: ${[...entry.pathCache.keys()].some((k) => k.startsWith('linear|')) && [...entry.pathCache.keys()].some((k) => k.startsWith('polar|'))}`);

    const t0 = performance.now();
    for (let width = 400; width < 1200; width += 20) {
        next.linearPath(audioData, { samples: 100, width, type: 'steps', top: 20 });
    }
    const t1 = performance.now();
    lines.push(`40 resize renders (width sweep): ${(t1 - t0).toFixed(1)} ms, pathCache size=${entry.pathCache.size}`);

    const t2 = performance.now();
    for (let samples = 50; samples <= 400; samples += 10) {
        next.linearPath(audioData, { samples, type: 'steps', top: 20 });
    }
    const t3 = performance.now();
    lines.push(`36 samples-sweep renders: ${(t3 - t2).toFixed(1)} ms, bucketCache size=${entry.bucketCache.size}, granules still=${entry.granMin.length}`);

    const a = next.linearPath(audioData, { samples: 123, type: 'steps', top: 20 });
    const b = next.linearPath(audioData, { samples: 123, type: 'steps', top: 20 });
    lines.push(`repeat render returns cached string: ${a === b}`);

    const n100 = countCommands(next.linearPath(audioData, { samples: 100, type: 'steps', top: 20 }))
        - countMoves(next.linearPath(audioData, { samples: 100, type: 'steps', top: 20 }));
    const n200 = countCommands(next.linearPath(audioData, { samples: 200, type: 'steps', top: 20 }))
        - countMoves(next.linearPath(audioData, { samples: 200, type: 'steps', top: 20 }));
    lines.push(`draw nodes samples=100 -> ${n100}, samples=200 -> ${n200}, scales as expected: ${n200 === n100 * 2}`);
};

// --- Phase 1: synthetic AudioBuffer, fully synchronous, virtual-time safe ---
const synthLines = [];
try {
    const length = 44100 * 60; // 2.646M samples, same scale as the demo ogg
    const synth = new AudioBuffer({ length, numberOfChannels: 1, sampleRate: 44100 });
    const channel = synth.getChannelData(0);
    let state = 7;
    const rand = () => {
        state = (state * 1664525 + 1013904223) >>> 0;
        return state / 4294967296;
    };
    for (let i = 0; i < length; i++) {
        channel[i] = Math.sin(i * 0.03) * (0.4 + rand() * 0.5);
        if (i > length / 2 && i < length / 2 + 20000) channel[i] = 0; // silent stretch
    }
    runChecks(synth, 'synthetic', synthLines);
} catch (error) {
    synthLines.push('SYNTH ERROR: ' + (error && error.stack || error));
}
report(synthLines);

// --- Phase 2: the real demo ogg, decoded off the main thread ---
try {
    const response = await fetch('../docs/hello_world.ogg');
    const arrayBuffer = await response.arrayBuffer();
    const audioContext = new OfflineAudioContext(1, arrayBuffer.byteLength || 1, 44100);
    const audioData = await audioContext.decodeAudioData(arrayBuffer);
    const oggLines = [...synthLines, '', '--- real hello_world.gg decoded ---'];
    runChecks(audioData, 'real-ogg', oggLines);
    report(oggLines);
} catch (error) {
    const lines = [...synthLines, '', 'OGG DECODE SKIPPED/FAILED: ' + (error && error.message || error)];
    report(lines);
}

